#ifndef MEP_GAP_LSP_VOCAB_H
#define MEP_GAP_LSP_VOCAB_H

// mep-gap-lsp's knowledge of GAP's global names, generated by
// tools/gen_gap_vocab.py (`just gap-vocab`) from GAP 4.15 and the packages
// distributed with it -- names, kinds and argument lists only: GAP's
// manuals are GPL, so no prose is copied.

#include <cstddef>

struct GapVocabEntry {
    const char *name;
    const char *kind;  // the manual's: Func, Oper, Attr, Prop, Filt, Var, Meth, InfoClass, Constr, Fam, Coll, Repr
    const char *args;  // the manual's argument list, e.g. "G, H[, opt]" (one per documented form, '|'-separated)
    const char *book;  // "ref", "tut", or the package's name
};

/** @brief Documented names (the manuals' index), sorted by name; a name with several entries appears once per form. */
extern const GapVocabEntry kGapVocab[];
extern const size_t kGapVocabSize;

/** @brief Every global name bound after starting GAP with its default packages, sorted (strcmp). */
extern const char *const kGapGlobals[];
extern const size_t kGapGlobalsSize;

#endif  // MEP_GAP_LSP_VOCAB_H
